/* AIVIC_FUNCTION_BUNDLE_START owner=anonymizeExpiredMealEvaluationData exports=anonymizeExpiredMealEvaluationData */
const __aivicBundle_16_anonymizeExpiredMealEvaluationData = (() => {
  function anonymizeExpiredMealEvaluationData(input: {
    evaluationData: Array<{
      id: string;
      userId: string;
      userName: string;
      mealId: string;
      satisfactionScore: number;
      completionRate: number;
      requestComment: string;
      registeredAt: Date;
    }>;
    policy: {
      retentionDays: number;
      anonymizeExpiredData: boolean;
    };
    currentDate: Date;
  }): {
    anonymized: Array<{
      id: string;
      userId: null;
      userName: null;
      mealId: string;
      satisfactionScore: number;
      completionRate: number;
      requestComment: string;
      registeredAt: Date;
    }>;
    retained: Array<{
      id: string;
      userId: string;
      userName: string;
      mealId: string;
      satisfactionScore: number;
      completionRate: number;
      requestComment: string;
      registeredAt: Date;
    }>;
  } {
    const { evaluationData, policy, currentDate } = input;
    const { retentionDays, anonymizeExpiredData } = policy;
  
    const anonymized: Array<{
      id: string;
      userId: null;
      userName: null;
      mealId: string;
      satisfactionScore: number;
      completionRate: number;
      requestComment: string;
      registeredAt: Date;
    }> = [];
    const retained: Array<{
      id: string;
      userId: string;
      userName: string;
      mealId: string;
      satisfactionScore: number;
      completionRate: number;
      requestComment: string;
      registeredAt: Date;
    }> = [];
  
    const retentionThresholdMs = retentionDays * 24 * 60 * 60 * 1000;
    const currentTimeMs = currentDate.getTime();
  
    for (const record of evaluationData) {
      const recordTimeMs = record.registeredAt.getTime();
      const ageMs = currentTimeMs - recordTimeMs;
      const isExpired = ageMs > retentionThresholdMs;
  
      if (isExpired && anonymizeExpiredData) {
        anonymized.push({
          id: record.id,
          userId: null,
          userName: null,
          mealId: record.mealId,
          satisfactionScore: record.satisfactionScore,
          completionRate: record.completionRate,
          requestComment: record.requestComment,
          registeredAt: record.registeredAt,
        });
      } else {
        retained.push({
          id: record.id,
          userId: record.userId,
          userName: record.userName,
          mealId: record.mealId,
          satisfactionScore: record.satisfactionScore,
          completionRate: record.completionRate,
          requestComment: record.requestComment,
          registeredAt: record.registeredAt,
        });
      }
    }
  
    return {
      anonymized,
      retained,
    };
  }
  return { anonymizeExpiredMealEvaluationData };
})();
export const anonymizeExpiredMealEvaluationData = __aivicBundle_16_anonymizeExpiredMealEvaluationData.anonymizeExpiredMealEvaluationData;
/* AIVIC_FUNCTION_BUNDLE_END owner=anonymizeExpiredMealEvaluationData */

